// Extract error details
const execution = $json.execution || {};
const workflow = $json.workflow || {};

const errorNode = execution.lastNodeExecuted || 'Unknown';
const errorMessage = execution.error?.message || 'Unknown error';
const errorStack = execution.error?.stack || '';
const executionId = execution.id || '';
const workflowName = workflow.name || 'Unknown';
const workflowId = workflow.id || '';

// Determine severity
let severity = 'medium';
if (errorNode.includes('Publish') || errorNode.includes('Instagram')) {
  severity = 'high';
} else if (errorNode.includes('Metrics') || errorNode.includes('Log') || errorNode.includes('Sheets')) {
  severity = 'low';
}

// Determine error stage
let errorStage = 'unknown';
if (errorNode.includes('RSS') || errorNode.includes('Perplexity') || errorNode.includes('SerpAPI')) {
  errorStage = 'research';
} else if (errorNode.includes('Curation') || errorNode.includes('Score')) {
  errorStage = 'curation';
} else if (errorNode.includes('Writer') || errorNode.includes('Editor') || errorNode.includes('SEO') || errorNode.includes('Researcher')) {
  errorStage = 'content_production';
} else if (errorNode.includes('DALL-E') || errorNode.includes('Image') || errorNode.includes('Unsplash')) {
  errorStage = 'image_generation';
} else if (errorNode.includes('Publish') || errorNode.includes('Blog') || errorNode.includes('Instagram')) {
  errorStage = 'publication';
}

const timestamp = new Date().toISOString();

return [{
  json: {
    severity,
    errorStage,
    errorNode,
    errorMessage,
    executionId,
    workflowName,
    workflowId,
    timestamp,
    errorStack: errorStack.substring(0, 500)
  }
}];

